'use strict';
const escapeText=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const menuButton=document.querySelector('.menu');
if(menuButton){const nav=document.querySelector('#navigation');menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});document.querySelectorAll('#navigation a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false')}));menuButton.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false')}});}
function showOpportunity(record){if(!record)return;document.querySelector('#detail-body').innerHTML=`<p class="provider">${escapeText(record.owner)}</p><h2 id="detail-title">${escapeText(record.title)}</h2><p>${escapeText(record.description)}</p><dl><dt>Who it’s for</dt><dd>${escapeText(record.eligibility)}</dd><dt>Format</dt><dd>${escapeText(record.delivery)}</dd><dt>Time</dt><dd>${escapeText(record.duration)}</dd><dt>Cost</dt><dd>${escapeText(record.cost)}</dd><dt>Journey connections</dt><dd>${escapeText((record.journeyStages||record.stages||[]).join(" · "))} (proposed mapping)</dd><dt>Availability</dt><dd>${escapeText(record.status)}</dd>${record.contact?`<dt>Provider contact</dt><dd>${escapeText(record.contact)}</dd>`:''}${record.notes?`<dt>Before you go</dt><dd>${escapeText(record.notes)}</dd>`:''}</dl><a class="button" href="${escapeText(record.url)}" target="_blank" rel="noopener">Visit the program website</a><p class="note">Provider information reviewed ${escapeText(record.checked||'September 16–17, 2026')}. Confirm current eligibility, session dates and registration with the provider.</p>`;document.querySelector('#detail').showModal();}
const closeButton=document.querySelector('.close');if(closeButton)closeButton.addEventListener('click',()=>document.querySelector('#detail').close());
function restoreFilters(mapping){const params=new URLSearchParams(window.location.search);for(const [key,id] of Object.entries(mapping)){const node=document.querySelector(id),raw=params.get(key),value=key==='stage'&&window.JourneyMapping?JourneyMapping.canonical(raw):raw;if(value===null||!node)continue;if(node.tagName!=='SELECT'||Array.from(node.options).some(o=>o.value===value))node.value=value;}}
function syncAudienceLinks(audience='Employees'){document.querySelectorAll('[data-carry-audience]').forEach(a=>{if(!a.dataset.baseHref)a.dataset.baseHref=a.getAttribute('href');const u=new URL(a.dataset.baseHref,window.location.href);const acceptsOther=u.pathname.endsWith('index.html')||u.pathname.endsWith('programs.html');const role=LeadershipDiscovery.employeeRoles.includes(audience)||acceptsOther?audience:'Employees';if(role!=='Employees')u.searchParams.set('audience',role);else u.searchParams.delete('audience');a.setAttribute('href',u.pathname.split('/').pop()+u.search+u.hash);});}
function saveFilters(state){const url=new URL(window.location.href);url.search='';for(const [key,value] of Object.entries(state)){if(value&&!(key==='audience'&&value==='Employees')&&!(key==='sort'&&value==='title'))url.searchParams.set(key,value);}window.history.replaceState(null,'',url.pathname+url.search+url.hash);syncAudienceLinks(state.audience||'Employees');}
function audienceHelp(audience,resources=false){if(audience==='FacultyFocus')return 'Academic and faculty development, including selected offerings for academic staff. Check each provider’s participation requirements.';if(audience==='Faculty')return resources?'Faculty-specific and shared employee resources. Faculty mentoring appears first.':'Faculty-specific and shared employee learning. Program selection and academic-role requirements still apply.';if(audience==='Staff')return 'Staff and shared employee learning. Check unit-specific requirements in each result.';if(audience==='Supervisors')return 'Learning for supervisors and people leaders. Academic or unit-specific requirements are shown with each offering.';if(audience==='Students')return 'Student opportunities are listed separately from employee development. Admission or program selection may apply.';if(audience==='System')return 'System and agency programs. Check your member institution’s participation requirements.';if(audience==='External')return 'Professional, public and admission-based offerings. Check costs and program requirements with the provider.';if(audience==='Other')return 'Student, System and external opportunities, separate from employee development.';return resources?'Resources for staff, faculty and people leaders. Audience tags describe relevance; provider access requirements still apply.':'Explore employee learning across Texas A&M. Each result shows who it serves; eligibility may depend on role or unit.';}
function renderFilterChips(selector,items,onClear){const box=document.querySelector(selector);box.innerHTML=items.filter(i=>i.value).map(i=>`<button type="button" class="filter-chip" data-clear-filter="${escapeText(i.key)}" aria-label="Clear ${escapeText(i.label)}">${escapeText(i.label)}<span aria-hidden="true">×</span></button>`).join('');box.hidden=!items.some(i=>i.value);box.querySelectorAll('[data-clear-filter]').forEach(b=>b.addEventListener('click',()=>onClear(b.dataset.clearFilter)));}
const initialAudience=new URLSearchParams(window.location.search).get('audience');if(window.LeadershipDiscovery)syncAudienceLinks(LeadershipDiscovery.labels[initialAudience]?initialAudience:'Employees');

function renderStageConnections(stage,audience='Employees'){
 const box=document.querySelector('#stage-connections');if(!box)return;
 const pages={'Start at A&M':'start-at-am','Lead Yourself':'lead-yourself','Lead People':'lead-people','Lead Teams':'lead-teams','Lead Across A&M':'lead-across-am','Develop Others':'develop-others'};
 const slug=pages[stage];box.hidden=!slug;if(!slug){box.replaceChildren();return;}
 const role=LeadershipDiscovery.employeeRoles.includes(audience)?audience:'Employees';
 const qs=new URLSearchParams({stage});if(role!=='Employees')qs.set('audience',role);
 const guide=slug+'.html'+(role!=='Employees'?'?audience='+encodeURIComponent(role):'');
 box.innerHTML='<strong>'+escapeText(stage)+'</strong><a href="'+escapeText(guide)+'">Learning &amp; resource guide →</a><a href="programs.html?'+escapeText(qs.toString())+'#opportunities">Courses, programs &amp; communities →</a><a href="toolkit.html?'+escapeText(qs.toString())+'#library">Tools &amp; resources →</a>';
}
